-- Zoho item map: sku -> zoho item_id
-- Run once in Supabase SQL Editor (or re-run to refresh)
create table if not exists public.zoho_item_map (
  sku     text primary key,
  item_id text not null
);
alter table public.zoho_item_map enable row level security;
-- No public policies; accessed only by edge function via service role key

truncate table public.zoho_item_map;
on conflict (sku) do update set item_id = excluded.item_id;

select count(*) as imported_rows from public.zoho_item_map;